"""Small, independent Parquet file reader for the terminal inspector.

The implementation reads the compact-protocol footer and page headers directly;
no external Parquet or dataframe implementation is used.
"""
import struct
import math
import zlib
import ctypes
import datetime
from dataclasses import dataclass, field

PHYSICAL = ['BOOLEAN', 'INT32', 'INT64', 'INT96', 'FLOAT', 'DOUBLE', 'BYTE_ARRAY', 'FIXED_LEN_BYTE_ARRAY']
ENCODINGS = {0:'PLAIN',1:'GROUP_VAR_INT',2:'PLAIN_DICTIONARY',3:'RLE',4:'BIT_PACKED',5:'DELTA_BINARY_PACKED',6:'DELTA_LENGTH_BYTE_ARRAY',7:'DELTA_BYTE_ARRAY',8:'RLE_DICTIONARY',9:'BYTE_STREAM_SPLIT'}
CODECS = {0:'UNCOMPRESSED',1:'SNAPPY',2:'GZIP(GzipLevel(6))',3:'LZO',4:'BROTLI(BrotliLevel(1))',5:'LZ4',6:'ZSTD(ZstdLevel(1))',7:'LZ4_RAW'}
REPETITION = ['REQUIRED', 'OPTIONAL', 'REPEATED']

class ParquetError(Exception):
    pass

class Compact:
    def __init__(self, data, pos=0):
        self.data = data
        self.pos = pos
    def byte(self):
        if self.pos >= len(self.data):
            raise ParquetError('Parquet error: EOF while reading compact protocol')
        x = self.data[self.pos]
        self.pos += 1
        return x
    def take(self, n):
        if n < 0 or self.pos+n > len(self.data):
            raise ParquetError('parquet: File out of specification: The page header reported the wrong page size')
        x = self.data[self.pos:self.pos+n]
        self.pos += n
        return x
    def uint(self):
        x = 0
        shift = 0
        while True:
            v = self.byte()
            x |= (v & 127) << shift
            if not v & 128:
                return x
            shift += 7
            if shift > 70:
                raise ParquetError('Parquet error: Invalid compact protocol integer')
    def sint(self):
        x = self.uint()
        return (x >> 1) ^ -(x & 1)
    def value(self, typ):
        if typ == 1: return True
        if typ == 2: return False
        if typ == 3: return self.byte()
        if typ in (4,5,6): return self.sint()
        if typ == 7: return struct.unpack('<d',self.take(8))[0]
        if typ == 8: return self.take(self.uint())
        if typ in (9,10):
            head = self.byte()
            n, t = head >> 4, head & 15
            if n == 15: n = self.uint()
            if n > 10000000: raise ParquetError('Parquet error: Invalid compact list')
            return [self.value(t) for _ in range(n)]
        if typ == 11:
            n = self.uint()
            types = self.byte() if n else 0
            return [(self.value(types >> 4),self.value(types & 15)) for _ in range(n)]
        if typ == 12: return self.read_struct()
        raise ParquetError('Parquet error: Invalid compact protocol type')
    def read_struct(self):
        obj = {}
        last = 0
        while True:
            head = self.byte()
            if head == 0: return obj
            delta, typ = head >> 4, head & 15
            idx = last + delta if delta else self.sint()
            last = idx
            obj[idx] = self.value(typ)

def text(x):
    if isinstance(x,bytes): return x.decode('utf-8','replace')
    return str(x)

def unpack_bits(data, width, count):
    if not width: return [0]*count
    result=[]
    acc=bits=0
    it=iter(data)
    mask=(1<<width)-1
    for _ in range(count):
        while bits < width:
            acc |= next(it,0) << bits
            bits += 8
        result.append(acc & mask)
        acc >>= width
        bits -= width
    return result

def hybrid(data,width,count):
    r = Compact(data)
    out=[]
    while len(out)<count and r.pos<len(data):
        head = r.uint()
        n=head>>1
        if not n: break
        if head & 1:
            size = n * width
            out.extend(unpack_bits(r.take(size),width,n*8))
        else:
            v=int.from_bytes(r.take((width+7)//8),'little')
            out.extend([v]*min(n,count-len(out)))
    return (out+[0]*max(0,count-len(out)))[:count]

def delta_packed(r):
    block = r.uint()
    mini = r.uint()
    count = r.uint()
    first = r.sint()
    if not count: return []
    if not block or not mini or block%mini: raise ParquetError('Parquet error: Invalid delta block')
    out=[first]
    cur=first
    nmini=block//mini
    while len(out)<count:
        minimum=r.sint()
        widths=[r.byte() for _ in range(mini)]
        for width in widths:
            vals=unpack_bits(r.take((nmini*width+7)//8),width,nmini)
            for val in vals:
                if len(out)<count:
                    cur += minimum+val
                    out.append(cur)
    return out

def snappy(data):
    r=Compact(data)
    size=r.uint()
    out=bytearray()
    while r.pos < len(data) and len(out)<size:
        tag=r.byte()
        kind=tag&3
        if kind==0:
            n=tag>>2
            if n<60: n+=1
            else: n=int.from_bytes(r.take(n-59),'little')+1
            out.extend(r.take(n))
        else:
            if kind==1:
                n=4+((tag>>2)&7)
                offset=((tag&224)<<3)|r.byte()
            elif kind==2:
                n=1+(tag>>2);offset=int.from_bytes(r.take(2),'little')
            else:
                n=1+(tag>>2);offset=int.from_bytes(r.take(4),'little')
            if not offset or offset>len(out): raise ParquetError('parquet: Invalid snappy copy')
            for _ in range(n): out.append(out[-offset])
    return bytes(out)

def lz4_raw(data):
    r=Compact(data)
    out=bytearray()
    def length(n):
        if n==15:
            while True:
                b=r.byte(); n+=b
                if b!=255: break
        return n
    while r.pos<len(data):
        token=r.byte()
        out.extend(r.take(length(token>>4)))
        if r.pos==len(data): break
        offset=int.from_bytes(r.take(2),'little')
        n=length(token&15)+4
        if offset==0 or offset>len(out): raise ParquetError('parquet: Invalid lz4 copy')
        for _ in range(n): out.append(out[-offset])
    return bytes(out)

_libs={}
def decompress(data,codec,size):
    if codec==0: return data
    if codec==1: return snappy(data)
    if codec==2: return zlib.decompress(data,31)
    if codec in (5,7):
        if codec==5 and len(data)>8:
            un,co=struct.unpack('>II',data[:8])
            if co<=len(data)-8 and un<=size:
                out=bytearray();pos=0
                try:
                    while pos<len(data):
                        un=struct.unpack('>I',data[pos:pos+4])[0];pos+=4
                        stop=len(out)+un
                        while len(out)<stop:
                            co=struct.unpack('>I',data[pos:pos+4])[0];pos+=4
                            out.extend(lz4_raw(data[pos:pos+co]));pos+=co
                    return bytes(out)
                except Exception: pass
        return lz4_raw(data)
    if codec==6:
        if codec not in _libs:
            lib=ctypes.CDLL('libzstd.so.1')
            lib.ZSTD_decompress.argtypes=[ctypes.c_void_p,ctypes.c_size_t,ctypes.c_void_p,ctypes.c_size_t]
            lib.ZSTD_decompress.restype=ctypes.c_size_t
            _libs[codec]=lib
        buf=ctypes.create_string_buffer(max(size,1))
        got=_libs[codec].ZSTD_decompress(buf,size,data,len(data))
        if got>size: raise ParquetError('parquet: ZSTD decompression error')
        return buf.raw[:got]
    if codec==4:
        if codec not in _libs:
            lib=ctypes.CDLL('libbrotlidec.so.1')
            lib.BrotliDecoderDecompress.argtypes=[ctypes.c_size_t,ctypes.c_void_p,ctypes.POINTER(ctypes.c_size_t),ctypes.c_void_p]
            _libs[codec]=lib
        buf=ctypes.create_string_buffer(max(size,1));sz=ctypes.c_size_t(size)
        if _libs[codec].BrotliDecoderDecompress(len(data),data,ctypes.byref(sz),buf)!=1:
            raise ParquetError('parquet: Brotli decompression error')
        return buf.raw[:sz.value]
    raise ParquetError('Parquet error: Unsupported compression codec')

@dataclass
class Node:
    info:dict
    parent:object=None
    children:list=field(default_factory=list)
    path:tuple=()
    depth:int=0
    deflevel:int=0
    replevel:int=0
    leaf:int=-1
    tree_label:str=''
    @property
    def name(self): return text(self.info.get(4,b''))
    @property
    def physical(self): return self.info.get(1)
    @property
    def repetition(self): return self.info.get(3,0)
    @property
    def converted(self): return self.info.get(6)
    @property
    def logical(self): return self.info.get(10,{})
    @property
    def is_list(self): return self.converted==3 or 3 in self.logical
    @property
    def is_string(self): return self.converted in (0,4,19) or 1 in self.logical or 4 in self.logical or 12 in self.logical

@dataclass
class Page:
    header:dict
    data:bytes
    offset:int
    @property
    def kind(self): return self.header.get(1,0)
    @property
    def sub(self): return self.header.get({0:5,2:7,3:8}.get(self.kind,5),{})
    @property
    def count(self): return self.sub.get(1,0)
    @property
    def encoding(self): return self.sub.get(4 if self.kind==3 else 2,0)

@dataclass
class Value:
    data:object
    kind:str=''
    scale:int=0

class Parquet:
    def __init__(self,path):
        self.path=path
        try:
            with open(path,'rb') as f: self.data=f.read()
        except OSError as ex:
            raise ParquetError(f'{ex.strerror} (os error {ex.errno})')
        if len(self.data)<8:
            raise ParquetError('Parquet error: Invalid Parquet file. Size is smaller than footer')
        if self.data[-4:]==b'PARE':
            raise ParquetError('Parquet error: Parquet file has an encrypted footer but the encryption feature is disabled')
        if self.data[-4:]!=b'PAR1':
            raise ParquetError('Parquet error: Invalid Parquet file. Corrupt footer')
        n=struct.unpack('<I',self.data[-8:-4])[0]
        if n+8>len(self.data):
            raise ParquetError(f'Parquet error: Invalid Parquet file. Footer size of {n} bytes exceeds file size of {len(self.data)} bytes')
        self.metadata=Compact(self.data,len(self.data)-8-n).read_struct()
        self.nodes=[];self.leaves=[]
        infos=iter(self.metadata.get(2,[]))
        def build(parent=None,prefix='',last=True):
            info=next(infos)
            physical=info.get(1)
            if physical is not None and physical not in range(8):
                raise ParquetError(f'Parquet error: unexpected parquet type: {physical}')
            node=Node(info,parent)
            if parent:
                node.path=parent.path+(node.name,)
                node.depth=parent.depth+1
                node.deflevel=parent.deflevel+(node.repetition in (1,2))
                node.replevel=parent.replevel+(node.repetition==2)
            node.tree_label=prefix+('└─ ' if last else '├─ ')+('root' if parent is None else node.name)
            self.nodes.append(node)
            if physical is None:
                num=info.get(5,0)
                for i in range(num): node.children.append(build(node,prefix+('   ' if last else '│  '),i==num-1))
            else:
                node.leaf=len(self.leaves);self.leaves.append(node)
            return node
        self.root=build()
        self.groups=self.metadata.get(4,[])
        self.num_rows=self.metadata.get(3,0)
        self.created_by=text(self.metadata.get(6,b''))
        self.page_cache={}
        self.rows=[]
        self._read_rows()

    def colmeta(self,group,leaf):
        cols=self.groups[group].get(1,[])
        return cols[leaf].get(3,{}) if leaf<len(cols) else {}

    def pages(self,group,leaf):
        key=(group,leaf)
        if key in self.page_cache: return self.page_cache[key]
        meta=self.colmeta(group,leaf)
        start=meta.get(11,meta.get(9,0))
        stop=start+meta.get(7,0)
        r=Compact(self.data,start)
        pages=[]
        while r.pos<stop and r.pos<len(self.data)-8:
            off=r.pos
            h=r.read_struct()
            if 1 not in h or 3 not in h: break
            n=h[3]
            if n<0 or h.get(2,0)<0:
                raise ParquetError('parquet: File out of specification: Number must be zero or positive: out of range integral type conversion attempted')
            if r.pos+n>stop:
                raise ParquetError('parquet: File out of specification: The page header reported the wrong page size')
            page=Page(h,r.take(n),off)
            if page.count<0:
                raise ParquetError('parquet: File out of specification: Number must be zero or positive: out of range integral type conversion attempted')
            pages.append(page)
        self.page_cache[key]=pages
        return pages

    def plain(self,data,node,count):
        r=Compact(data);typ=node.physical
        if typ==0: return [bool(x) for x in unpack_bits(data,1,count)]
        if typ in (1,2,4,5):
            fmt,size={1:('i',4),2:('q',8),4:('f',4),5:('d',8)}[typ]
            return list(struct.unpack('<'+fmt*count,r.take(size*count)))
        if typ==3: return [r.take(12) for _ in range(count)]
        if typ==6: return [r.take(int.from_bytes(r.take(4),'little')) for _ in range(count)]
        if typ==7: return [r.take(node.info.get(2,0)) for _ in range(count)]
        return []

    def encoded(self,data,node,count,encoding,dictionary):
        if not count: return []
        if encoding==0: return self.plain(data,node,count)
        if encoding in (2,8):
            if not data: return [None]*count
            indices=hybrid(data[1:],data[0],count)
            return [dictionary[i] if i<len(dictionary) else None for i in indices]
        if encoding==3:
            if len(data)>=4:
                size=int.from_bytes(data[:4],'little')
                payload=data[4:4+size]
            else: payload=data
            return [bool(x) for x in hybrid(payload,1,count)]
        if encoding==5: return delta_packed(Compact(data))[:count]
        if encoding in (6,7):
            r=Compact(data)
            prefixes=delta_packed(r) if encoding==7 else None
            lengths=delta_packed(r)
            out=[];last=b''
            for i,n in enumerate(lengths):
                v=(last[:prefixes[i]] if prefixes is not None else b'')+r.take(n)
                out.append(v);last=v
            return out[:count]
        if encoding==9:
            size={1:4,2:8,4:4,5:8,7:node.info.get(2,0)}.get(node.physical,4)
            plain=bytes(data[k*count+i] for i in range(count) for k in range(size))
            return self.plain(plain,node,count)
        raise ParquetError(f'Parquet error: Unsupported encoding {encoding}')

    def column_values(self,group,node):
        meta=self.colmeta(group,node.leaf)
        codec=meta.get(4,0)
        dictionary=[];entries=[]
        for page in self.pages(group,node.leaf):
            if page.kind==2:
                raw=decompress(page.data,codec,page.header[2])
                dictionary=self.plain(raw,node,page.count)
                continue
            if page.kind not in (0,3): continue
            n=page.count
            rb=node.replevel.bit_length();db=node.deflevel.bit_length()
            if page.kind==0:
                r=Compact(decompress(page.data,codec,page.header[2]))
                if rb:
                    if page.sub.get(4,3)==4:
                        reps=unpack_bits(r.take((n*rb+7)//8),rb,n)
                    else: reps=hybrid(r.take(int.from_bytes(r.take(4),'little')),rb,n)
                else: reps=[0]*n
                if db:
                    if page.sub.get(3,3)==4:
                        defs=unpack_bits(r.take((n*db+7)//8),db,n)
                    else: defs=hybrid(r.take(int.from_bytes(r.take(4),'little')),db,n)
                else: defs=[0]*n
                raw=r.data[r.pos:]
            else:
                rl=page.sub.get(6,0);dl=page.sub.get(5,0)
                reps=hybrid(page.data[:rl],rb,n) if rb else [0]*n
                defs=hybrid(page.data[rl:rl+dl],db,n) if db else [0]*n
                raw=page.data[rl+dl:]
                if page.sub.get(7,True): raw=decompress(raw,codec,page.header[2]-rl-dl)
            count=sum(d==node.deflevel for d in defs)
            vals=iter(self.encoded(raw,node,count,page.encoding,dictionary))
            for rep,df in zip(reps,defs):
                val=next(vals,None) if df==node.deflevel else None
                entries.append((rep,df,val))
