        for rep,df,val in entries:
            if rep==0 and row:
                rows.append(row);row=[]
            row.append((rep,df,val))
        if row: rows.append(row)
        return rows

    def converted_value(self,node,val):
        if val is None: return None
        typ=node.physical;c=node.converted;l=node.logical
        if typ==0: return Value(val,'bool')
        if typ in (4,5): return None if math.isnan(val) else Value(val,'float')
        if typ==3:
            nano=int.from_bytes(val[:8],'little');jd=int.from_bytes(val[8:12],'little')
            try:
                dt=datetime.datetime(1970,1,1)+datetime.timedelta(days=jd-2440588,seconds=nano//1000000000)
                date=dt.strftime('%Y-%m-%d %H:%M:%S')
                fraction=nano%1000000000
                if fraction: date+='.'+f'{fraction:09d}'.rstrip('0')
                return Value(date,'date')
            except Exception: return Value(str(jd),'date')
        dec=l.get(5,{})
        if (c==5 or dec) and typ in (1,2,7):
            scale=node.info.get(7,dec.get(1,0))
            val=int.from_bytes(val,'big',signed=True) if isinstance(val,bytes) else val
            return Value(val,'decimal',scale)
        if c==6 or 6 in l:
            try: return Value(str(datetime.date(1970,1,1)+datetime.timedelta(days=val)),'date')
            except Exception: return Value(str(val),'date')
        if c in (9,10) or 8 in l:
            unit=1000 if c==9 else 1000000
            if 8 in l:
                units=l[8].get(2,{})
                unit=1000 if 1 in units else 1000000 if 2 in units else 1000000000
            sec,part=divmod(val,unit)
            try:
                dt=datetime.datetime(1970,1,1)+datetime.timedelta(seconds=sec)
                date=dt.strftime('%Y-%m-%d %H:%M:%S')
                if part: date+='.'+str(part).zfill(len(str(unit))-1).rstrip('0')
                return Value(date,'date')
            except Exception: return Value(str(val),'date')
        if c in (7,8) or 7 in l:
            unit=1000 if c==7 else 1000000
            if 7 in l:
                units=l[7].get(2,{})
                unit=1000 if 1 in units else 1000000 if 2 in units else 1000000000
            seconds,fraction=divmod(val,unit)
            v=f'{seconds//3600:02}:{seconds//60%60:02}:{seconds%60:02}'
            if fraction: v+='.'+str(fraction).zfill(len(str(unit))-1).rstrip('0')
            return Value(v,'date')
        if typ in (6,7):
            return Value(text(val) if node.is_string else val,'str' if node.is_string else 'bytes')
        if c in (11,12,13,14): val &= (1 << {11:8,12:16,13:32,14:64}[c])-1
