    def _read_rows(self):
        for gi,rg in enumerate(self.groups):
            n=rg.get(3,0)
            cols={leaf.leaf:self.column_values(gi,leaf) for leaf in self.leaves}
            # Unannotated repeated struct columns are not materialized by this view.
            unsupported=any(node.repetition==2 and node.parent and not node.parent.is_list and node.parent.parent is self.root for node in self.nodes if node.children)
            if unsupported: continue
            def leaf_ids(node):
                return [node.leaf] if node.leaf>=0 else [i for child in node.children for i in leaf_ids(child)]
            ids={id(node):leaf_ids(node) for node in self.nodes}
            def sample(node,parts):
                for i in ids[id(node)]:
                    if parts.get(i): return parts[i][0][1]
                return -1
            def materialize(node,parts,skip_repeat=False):
                df=sample(node,parts)
                if node.repetition==2 and not skip_repeat:
                    if df<node.deflevel: return Value([],'list')
                    split={}
                    m=0
                    for i in ids[id(node)]:
                        groups=[];group=[]
                        for ent in parts.get(i,[]):
                            if group and ent[0]<=node.replevel:
                                groups.append(group);group=[]
                            group.append(ent)
                        if group: groups.append(group)
