"""Formatting shared by the four terminal views."""
import math
import unicodedata

def cell_width(ch):
    if ord(ch)<32 or 127<=ord(ch)<160: return 0
    if unicodedata.combining(ch): return 0
    return 2 if unicodedata.east_asian_width(ch) in ('W','F') else 1

def width(s): return sum(cell_width(ch) for ch in s)

def clip(s,n):
    if n<=0: return ''
    out=[];w=0
    for ch in str(s):
        k=cell_width(ch)
        if k+w>n: break
        if k or (ord(ch)>=32 and ord(ch)!=127): out.append(ch)
        w+=k
    return ''.join(out)

def padded(s,n,align='left'):
    s=clip(str(s),n)
    spaces=max(0,n-width(s))
    if align=='right': return ' '*spaces+s
    if align=='center': return ' '*(spaces//2)+s+' '*(spaces-spaces//2)
    return s+' '*spaces

def ellipsis(s,n=25):
    if width(s)>n: return clip(s,n-1)+'…'
    return s

def pretty_size(size):
    if size<1024: return f'{size} B'
    for unit in ['KiB','MiB','GiB','TiB','PiB']:
        size/=1024
        if size<1024: return f'{size:.2f} {unit}'
    return f'{size:.2f} EiB'

def ratio(raw,compressed):
    return raw/compressed if compressed else (float('nan') if not raw else float('inf'))

def fixed_float(v,n=2):
    if math.isnan(v): return 'NaN'
    if math.isinf(v): return 'inf' if v>0 else '-inf'
    return f'{v:.{n}f}'

def data_float(v):
    if math.isnan(v): return 'NaN'
    if math.isinf(v): return 'inf' if v>0 else '-inf'
    a=abs(v)
    if a and (a<0.000001 or a>=1000000):
        s=f'{v:.4e}'
        mantissa,exp=s.split('e')
        mantissa=mantissa.rstrip('0').rstrip('.')
        return mantissa+'e'+str(int(exp))
    s=f'{v:.6f}'.rstrip('0')
    if s.endswith('.'): s+='0'
    return s

def bytes_string(v):
    out=['b"']
    for byte in v:
        if 33<=byte<=126 and byte not in (34,92): out.append(chr(byte))
        elif byte==34: out.append('\\"')
        elif byte==92: out.append('\\\\')
        elif byte==10: out.append('\\n')
        elif byte==13: out.append('\\r')
        elif byte==9: out.append('\\t')
        else: out.append(f'\\x{byte:02x}')
    out.append('"')
    return ''.join(out)

def value_string(value,nested=False):
    if value is None: return 'null' if nested else 'NULL'
    v=value.data;k=value.kind
    if k=='str': return '"'+v+'"'
    if k=='bytes': return bytes_string(v)
    if k=='bool': return 'true' if v else 'false'
    if k=='float': return data_float(v)
    if k=='decimal':
        n=value.scale
        if n<=0: return str(v*10**-n)
        s=str(abs(v)).zfill(n+1)
        return ('-' if v<0 else '')+s[:-n]+'.'+s[-n:]
    if k=='struct': return '{'+','.join(value_string(x,True) for x in v)+'}'
    if k=='list':
        if len(v)>3:
            content=', '.join(value_string(x,True) for x in v[:2])+', … '+value_string(v[-1],True)
        else: content=', '.join(value_string(x,True) for x in v)
        return '['+content+']'
    return str(v)
