"""A minimal styled cell surface with deterministic terminal rendering."""
from formatting import width, clip, cell_width

DEFAULT=()
def style(fg=None,bg=None,bold=False,underline=False,reverse=False):
    return (fg,bg,bold,underline,reverse)
WHITE=style(15)
GREEN=style(2)
BLUE=style(4)
GRAY=style(8)
YELLOW=style(3)
BOLDYELLOW=style(3,bold=True)
SELECT=style(0,3)

class Screen:
    def __init__(self,w,h):
        self.w=max(w,1);self.h=max(h,1)
        self.grid=[[(' ',DEFAULT) for _ in range(self.w)] for _ in range(self.h)]
    def put(self,x,y,s,st=DEFAULT,limit=None):
        if y<0 or y>=self.h: return
        end=self.w if limit is None else min(self.w,x+limit)
        for ch in str(s):
            cw=cell_width(ch)
            if cw==0:
                continue
            if x+cw>end: break
            if x>=0:
                self.grid[y][x]=(ch,st)
                for k in range(1,cw): self.grid[y][x+k]=('',st)
            x+=cw
    def fill(self,x,y,w,h,ch=' ',st=DEFAULT):
        for yy in range(max(0,y),min(self.h,y+h)):
            for xx in range(max(0,x),min(self.w,x+w)):
                self.grid[yy][xx]=(ch,st)
    def hline(self,x,y,w,ch='─',st=DEFAULT): self.fill(x,y,w,1,ch,st)
    def styled(self,x,y,segments,limit=None):
        stop=self.w if limit is None else min(self.w,x+limit)
        for s,st in segments:
            self.put(x,y,s,st,max(0,stop-x));x+=width(s)
    def box(self,x,y,w,h,rounded=False,title='',title_style=DEFAULT,border_style=DEFAULT,center_title=False,bottom=None):
        if w<2 or h<2: return
        tl,tr,bl,br=('╭','╮','╰','╯') if rounded else ('┌','┐','└','┘')
        self.hline(x+1,y,w-2,st=border_style);self.hline(x+1,y+h-1,w-2,st=border_style)
        for yy in range(y+1,y+h-1):
            self.put(x,yy,'│',border_style);self.put(x+w-1,yy,'│',border_style)
        self.put(x,y,tl,border_style);self.put(x+w-1,y,tr,border_style)
        self.put(x,y+h-1,bl,border_style);self.put(x+w-1,y+h-1,br,border_style)
        if title:
            tx=x+max(1,(w-width(title))//2) if center_title else x+1
            self.put(tx,y,title,title_style,max(0,x+w-1-tx))
        if bottom:
            text=''.join(s for s,_ in bottom)
            start=x+(w-width(text))//2
            # Centered titles are clipped on either side of the inner border.
            offset=max(0,x+1-start)
            for s,st in bottom:
                sw=width(s)
                if offset>=sw: offset-=sw;start+=sw;continue
                if offset:
                    s=s[offset:];start+=offset;offset=0
                self.put(start,y+h-1,s,st,max(0,x+w-1-start));start+=width(s)
    def plain(self): return '\n'.join(''.join(ch for ch,_ in row).rstrip() for row in self.grid)+'\n'
    def ansi(self):
        out=['\x1b[?25l']
        cur=None
        for y,row in enumerate(self.grid):
            out.append(f'\x1b[{y+1};1H')
            for ch,st in row:
                if not ch: continue
                if st!=cur:
                    out.append(ansi_style(st));cur=st
                out.append(ch)
        out.append('\x1b[0m')
        return ''.join(out)

def ansi_style(st):
    if not st: return '\x1b[0m'
    fg,bg,bold,underline,reverse=st
    parts=['0']
    if bold: parts.append('1')
    if underline: parts.append('4')
    if reverse: parts.append('7')
    for color,is_bg in [(fg,False),(bg,True)]:
