"""Create small independent fixtures for testing the reader and terminal views."""
import struct

def uint(n):
    b=bytearray()
    while n>=128: b.append((n&127)|128);n>>=7
    b.append(n)
    return bytes(b)

def sint(n): return uint(n*2 if n>=0 else -n*2-1)

def value(t,v):
    if t in (1,2): return b''
    if t in (4,5,6): return sint(v)
    if t==3: return bytes([v])
    if t==8:
        if isinstance(v,str): v=v.encode()
        return uint(len(v))+v
    if t==9:
        typ,vs=v
        b=bytes([min(len(vs),15)<<4|typ])
        if len(vs)>=15: b+=uint(len(vs))
        return b+b''.join(value(typ,x) for x in vs)
    if t==12: return structure(v)
    raise ValueError(t)

def structure(fields):
    out=b'';last=0
    for idx,(typ,v) in sorted(fields.items()):
        diff=idx-last
        out+=bytes([(diff<<4)|typ]) if 1<=diff<=15 else bytes([typ])+sint(idx)
        out+=value(typ,v);last=idx
    return out+b'\0'

def make(path,columns,groups=None,created='fixture writer',stats=True):
    """columns are (name, physical type, converted type, values)."""
    count=len(columns[0][3]) if columns else 0
    if groups is None: groups=[count]
    schema=[{3:(5,0),4:(8,'schema'),5:(5,len(columns))}]
    for name,t,c,vals in columns:
        f={1:(5,t),3:(5,0),4:(8,name)}
        if c is not None: f[6]=(5,c)
        schema.append(f)
    result=b'PAR1';rgs=[];start=0
    for n in groups:
        chunks=[];total=0;rgstart=len(result)
        for name,t,c,allvals in columns:
            vals=allvals[start:start+n]
            def raw(v):
                if t in (1,2,4,5): return struct.pack({1:'<i',2:'<q',4:'<f',5:'<d'}[t],v)
                if t==0: return bytes([bool(v)])
                return v.encode() if isinstance(v,str) else v
            if t==0:
                data=bytes(sum((bool(v)<<j) for j,v in enumerate(vals[i:i+8])) for i in range(0,len(vals),8))
            elif t==6:
                data=b''.join(struct.pack('<I',len(raw(v)))+raw(v) for v in vals)
            else: data=b''.join(raw(v) for v in vals)
            off=len(result)
            page=structure({1:(5,0),2:(5,len(data)),3:(5,len(data)),5:(12,{1:(5,n),2:(5,0),3:(5,3),4:(5,3)})})+data
            result+=page;total+=len(page)
            meta={1:(5,t),2:(9,(5,[0])),3:(9,(8,[name])),4:(5,0),5:(6,n),6:(6,len(page)),7:(6,len(page)),9:(6,off)}
            if stats and vals:
                meta[12]=(12,{3:(6,0),5:(8,raw(max(vals))),6:(8,raw(min(vals)))})
            chunks.append({2:(6,off),3:(12,meta)})
        rgs.append({1:(9,(12,chunks)),2:(6,total),3:(6,n),5:(6,rgstart),6:(6,total)})
        start+=n
    footer={1:(5,2),2:(9,(12,schema)),3:(6,count),4:(9,(12,rgs))}
    if created is not None: footer[6]=(8,created)
    data=structure(footer)
    with open(path,'wb') as f:f.write(result+data+struct.pack('<I',len(data))+b'PAR1')
